-- Questões originais de estudo: Deitel e Deitel, Java: como programar, 10ª edição.
-- Tradução brasileira do PDF fornecido: Pearson Education do Brasil, 2017.
-- Contexto dos recursos: Java SE 8. Não são questões oficiais nem exercícios transcritos.
-- Execute após configurar public.questions, usando uma conta administrativa.
-- Todos os itens entram como rascunhos. Revise antes de publicar.
-- Páginas são do arquivo PDF, não da numeração impressa.
-- IDs fixos: reexecutar não duplica nem sobrescreve registros existentes.
-- Capítulo 4: Instruções de controle: parte 1; operadores de atribuição ++ e -- — 20 questões.
BEGIN;
SET LOCAL standard_conforming_strings = on;

INSERT INTO public.questions (
  id, year, question_type, subject, exam, question_number, topic, difficulty,
  statement, options, correct_option, explanation, source, is_annulled, is_published
) VALUES
('15030d18-20e5-525e-a500-0559934146c9', NULL, 'bibliography', 'Informática', 'CP-T', 1, 'Linguagem de Programação', 'Fácil', 'Um algoritmo define principalmente:', '["Um arquivo .class.","Uma interface gráfica.","Uma sequência de ações para resolver um problema.","A frequência do processador.","Somente uma classe pública."]'::jsonb, 2, 'A ordem e as condições de execução integram a solução.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 4, seção 4.2, páginas 115 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('7df8d524-5887-56f5-9048-2306d817052d', NULL, 'bibliography', 'Informática', 'CP-T', 2, 'Linguagem de Programação', 'Fácil', 'Qual finalidade tem o pseudocódigo?', '["Executar diretamente na JVM.","Planejar a lógica sem exigir sintaxe Java estrita.","Substituir bytecode.","Dispensar um algoritmo.","Definir somente variáveis."]'::jsonb, 1, 'Pseudocódigo é uma representação informal de soluções.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 4, seção 4.3, páginas 115 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('b2375ba4-3841-503d-9b34-38253027edf1', NULL, 'bibliography', 'Informática', 'CP-T', 3, 'Linguagem de Programação', 'Fácil', 'Qual estrutura escolhe caminhos conforme uma condição?', '["Sequência apenas.","Declaração import.","Pacote.","Comentário.","Seleção."]'::jsonb, 4, 'If e if…else são estruturas de seleção.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 4, seção 4.4, páginas 116 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('5d5a2279-d9e8-5809-bcf5-2cc5f0caed0f', NULL, 'bibliography', 'Informática', 'CP-T', 4, 'Linguagem de Programação', 'Médio', 'Se `int x=4; if(x>5) x++;`, qual é x?', '["4.","6.","3.","5.","Erro."]'::jsonb, 0, 'A condição é falsa e o incremento não ocorre.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 4, seção 4.5, páginas 117 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('1e0b3bf3-a227-57d1-a4cf-19542e1cdd61', NULL, 'bibliography', 'Informática', 'CP-T', 5, 'Linguagem de Programação', 'Médio', 'O else associa-se, sem chaves que determinem outra estrutura, ao:', '["If anterior mais próximo ainda sem else.","Método main.","Último while.","Primeiro if do arquivo.","Pacote da classe."]'::jsonb, 0, 'Chaves tornam explícita a estrutura de seleções aninhadas.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 4, seção 4.6, páginas 118–121 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('744948b2-3648-53cd-b455-823698c80d01', NULL, 'bibliography', 'Informática', 'CP-T', 6, 'Linguagem de Programação', 'Médio', 'Qual resultado de `int x=2; int y=x>3?10:20;`?', '["y=0.","Erro.","y=2.","y=20.","y=10."]'::jsonb, 3, 'O operador condicional escolhe a expressão correspondente ao teste falso.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 4, seção 4.6, páginas 118–121 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('78725538-acdb-5460-9b74-b355af8ba74b', NULL, 'bibliography', 'Informática', 'CP-T', 7, 'Linguagem de Programação', 'Médio', 'Um while pode executar seu corpo zero vezes?', '["Somente se houver break.","Não, é igual ao do…while.","Somente com arrays.","Sim, se a condição inicial for falsa.","Não, executa sempre uma vez."]'::jsonb, 3, 'O teste do while antecede o corpo.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 4, seção 4.8, páginas 124 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c647cf87-889b-5aab-8276-e25a81d98953', NULL, 'bibliography', 'Informática', 'CP-T', 8, 'Linguagem de Programação', 'Médio', 'Após `int n=1; while(n<5) n*=2;`, qual é n?', '["16.","2.","4.","8.","5."]'::jsonb, 3, 'Os valores produzidos são 2, 4 e 8; então o teste falha.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 4, seção 4.8, páginas 124 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('0364baf5-7ef9-5889-baef-f68045f1a77e', NULL, 'bibliography', 'Informática', 'CP-T', 9, 'Linguagem de Programação', 'Médio', 'Após `int n=0; while(n<3){n++;}`, qual é n?', '["4.","0.","3.","2.","1."]'::jsonb, 2, 'O incremento ocorre três vezes.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 4, seção 4.8, páginas 124 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('c6b476e6-fc16-50bd-890c-8c49a20fbc85', NULL, 'bibliography', 'Informática', 'CP-T', 10, 'Linguagem de Programação', 'Médio', 'Um contador controla normalmente:', '["Somente a soma dos valores.","O tipo do pacote.","A referência this.","Quantas repetições ocorreram.","A assinatura do método."]'::jsonb, 3, 'Contador e acumulador possuem papéis diferentes.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 4, seção 4.9, páginas 125–127 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('2a49e30e-7df9-51e0-b0d0-168435705a10', NULL, 'bibliography', 'Informática', 'CP-T', 11, 'Linguagem de Programação', 'Médio', 'Qual papel tem um acumulador?', '["Contar sempre por um exclusivamente.","Combinar valores sucessivos, por exemplo em uma soma.","Escolher nomes de classes.","Executar imports.","Impedir repetições."]'::jsonb, 1, 'O valor acumulado é atualizado durante o processamento.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 4, seção 4.9, páginas 125–127 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('96cdd5f8-7497-5d7f-89f7-39ad70827a64', NULL, 'bibliography', 'Informática', 'CP-T', 12, 'Linguagem de Programação', 'Médio', 'Para entradas 4, 6 e 7, soma 17 e contador 3, qual expressão preserva a fração da média?', '["`(double) soma / contador`.","`soma % contador`.","`soma / contador` sempre como double.","`(double)(soma / contador)`.","`contador / soma`."]'::jsonb, 0, 'Converter antes da divisão evita truncar a média por divisão inteira.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 4, seção 4.9, páginas 125–127 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('8ba64ad4-7e0b-53c5-ad48-fc6ada0e6b52', NULL, 'bibliography', 'Informática', 'CP-T', 13, 'Linguagem de Programação', 'Médio', 'Uma sentinela na leitura de dados representa:', '["Um tipo primitivo novo.","Um valor especial de término.","Uma exceção sempre lançada.","Um contador crescente.","Um dado obrigatoriamente incluído na média."]'::jsonb, 1, 'A sentinela deve ser reconhecida sem contaminar os cálculos dos dados válidos.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 4, seção 4.10, páginas 128–132 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('a9499722-9515-5495-b92e-4cbc6ddc0f11', NULL, 'bibliography', 'Informática', 'CP-T', 14, 'Linguagem de Programação', 'Médio', 'Por que validar contador antes de calcular média?', '["Para garantir que todos os valores sejam iguais.","Para eliminar o loop.","Para evitar dividir por zero quando não há dados válidos.","Para converter a sentinela em dado.","Para criar um objeto."]'::jsonb, 2, 'Nenhuma entrada válida deixa o contador em zero.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 4, seção 4.10, páginas 128–132 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('6e7605ba-f3dc-5d2f-a347-44231d691ba0', NULL, 'bibliography', 'Informática', 'CP-T', 15, 'Linguagem de Programação', 'Médio', 'Após `int x=4; x+=3;`, qual é x?', '["1.","12.","3.","4.","7."]'::jsonb, 4, 'A atribuição composta soma e armazena o resultado.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 4, seção 4.12, páginas 137–139 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('63e49254-3469-51f2-843f-9873094873f1', NULL, 'bibliography', 'Informática', 'CP-T', 16, 'Linguagem de Programação', 'Médio', 'Após `int x=5; int y=x++;`, quais são x e y?', '["5 e 5.","6 e 5.","4 e 5.","5 e 6.","6 e 6."]'::jsonb, 1, 'O pós-incremento produz o valor anterior e incrementa x.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 4, seção 4.13, páginas 137–139 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('3d4796f8-17ba-5559-bb0a-9514ca2e93d1', NULL, 'bibliography', 'Informática', 'CP-T', 17, 'Linguagem de Programação', 'Médio', 'Após `int x=5; int y=++x;`, quais são x e y?', '["4 e 4.","5 e 6.","6 e 5.","5 e 5.","6 e 6."]'::jsonb, 4, 'O pré-incremento incrementa antes de produzir o valor da expressão.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 4, seção 4.13, páginas 137–139 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('1614247c-b39b-5c57-ade1-323e8d2a79f8', NULL, 'bibliography', 'Informática', 'CP-T', 18, 'Linguagem de Programação', 'Médio', 'Um loop externo de três iterações contém outro de duas, sem desvios. Quantas execuções do corpo interno?', '["9.","3.","2.","5.","6."]'::jsonb, 4, 'Cada iteração externa executa as duas iterações internas.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 4, seção 4.11, páginas 133–136 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('1a9ab51f-67db-5379-9017-ab491d13a6fd', NULL, 'bibliography', 'Informática', 'CP-T', 19, 'Linguagem de Programação', 'Médio', 'Qual tipo primitivo representa valores verdadeiro e falso?', '["String.","Boolean.","boolean.","Object.","byte exclusivamente."]'::jsonb, 2, 'Boolean é classe empacotadora; boolean é o primitivo.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 4, seção 4.14, páginas 140–142 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false),
('b4b6630b-74d7-5c26-b52d-407a4ee08a39', NULL, 'bibliography', 'Informática', 'CP-T', 20, 'Linguagem de Programação', 'Médio', 'Qual tipo primitivo representa números de ponto flutuante de dupla precisão?', '["double.","char.","long.","boolean.","int."]'::jsonb, 0, 'Double e double também se distinguem como classe e primitivo.', 'DEITEL, Paul; DEITEL, Harvey. Java: como programar. Tradução da 10ª edição norte-americana. Pearson Education do Brasil, 2017. Capítulo 4, seção 4.14, páginas 140–142 do PDF fornecido. Contexto: Java SE 8. Questão original de estudo; não é questão oficial do CP-T.', false, false)
